import{_ as t,o as s,c as o,ao as a}from"./chunks/framework.D7TN4pt9.js";const u=JSON.parse('{"title":"Per-Machine Setup","description":"","frontmatter":{},"headers":[],"relativePath":"start/setup.md","filePath":"start/setup.md","lastUpdated":null}'),n={name:"start/setup.md"};function i(r,e,l,h,d,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="Per-Machine-Setup" tabindex="-1">Per-Machine Setup <a class="header-anchor" href="#Per-Machine-Setup" aria-label="Permalink to &quot;Per-Machine Setup {#Per-Machine-Setup}&quot;">​</a></h1><p>Ship of Tools runs across machines and operating systems, and each one needs a small amount of local state: the toolchains, a host registry, frontend settings, and a launcher.</p><div class="tip custom-block"><p class="custom-block-title">Guided or manual</p><p>The guided flow ships as the <strong><code>/sot-setup</code> Claude Code skill</strong> — available directly in any checkout (<code>.claude/skills/sot-setup/</code>) and installed user-level by <code>ShipTools.update_comm()</code>. There is no standalone <code>sot-setup</code> binary: in an agent session invoke <code>/sot-setup</code>; otherwise follow the checklist below manually. The Linux/macOS release installer (<code>scripts/install.sh</code>) automates much of this for packaged installs.</p></div><h2 id="Source-Setup-Checklist" tabindex="-1">Source Setup Checklist <a class="header-anchor" href="#Source-Setup-Checklist" aria-label="Permalink to &quot;Source Setup Checklist {#Source-Setup-Checklist}&quot;">​</a></h2><p>The <code>sot-setup</code> flow is a one-shot, cross-OS onboarding for a Ship of Tools machine (Windows, Linux, or macOS). Done manually, these are the steps:</p><ol><li><p><strong>Install the toolchains.</strong> Rust via <a href="https://rustup.rs/" target="_blank" rel="noreferrer">rustup</a> and Julia via <a href="https://github.com/JuliaLang/juliaup" target="_blank" rel="noreferrer">juliaup</a>, where they are missing.</p></li><li><p><strong>Build the Rust workspace</strong> (<code>rust/</code>) — the frontend and backend binaries.</p></li><li><p><strong>Ask a short Q&amp;A</strong> — your machine&#39;s role and, if it talks to a remote backend, that server&#39;s details (see below).</p></li><li><p><strong>Instantiate Julia environments</strong>: the repo root, <code>core</code>, <code>julia/kernel</code>, <code>julia/repl</code>, and <code>julia/pluto</code>.</p></li><li><p><strong>Write <code>hosts.toml</code></strong> (the hub&#39;s canonical copy, or a <code>sotd topology sync --hub &lt;alias&gt;</code> fetch of it) <strong>and <code>.sot/settings.toml</code></strong> from your answers.</p></li><li><p><strong>Install agent comm resources</strong>: <code>julia --project=. -e &#39;using ShipTools; ShipTools.update_comm()&#39;</code>.</p></li><li><p><strong>Create a launcher / shortcut</strong> so you can start the app without typing the build paths.</p></li></ol><p>On Windows frontend machines, run <code>scripts\\install-shortcut.ps1 -Hub &lt;hub-ssh-alias&gt;</code>; the launcher refreshes <code>hosts.toml</code> from the hub at every launch (see <a href="./../ref/config">Configuration Files</a>). Besides creating the desktop shortcut to <code>scripts\\launch-sot.ps1</code>, it sets the SoT icon (<code>logo.ico</code>) and stamps the <code>ShipOfTools.Sot</code> AppUserModelID on the <code>.lnk</code>, so the running window merges into the shortcut&#39;s taskbar button with the right icon (a hand-made shortcut gets neither). Re-run it after pinning to the taskbar so the pin is repointed to the launcher.</p><h2 id="The-cross-OS-topology" tabindex="-1">The cross-OS topology <a class="header-anchor" href="#The-cross-OS-topology" aria-label="Permalink to &quot;The cross-OS topology {#The-cross-OS-topology}&quot;">​</a></h2><p>The setup question that matters most is <em>which role this machine plays</em>. A Linux frontend is first-class, same as Windows or a Mac; the split that matters is backend vs. frontend, not one OS vs. another:</p><ul><li><p><strong>The backend runs on Linux.</strong> The daemon and the Julia kernel run on a Linux server (for example <code>myserver</code>). The daemon runs under the <code>systemd --user</code> unit <code>sotd.service</code>, and each session runs in its own capsule, so both survive SSH drops.</p></li><li><p><strong>The frontend</strong> — the native window that renders previews and owns the keyboard — runs on the machine in front of you: Linux, Windows or a Mac.</p></li><li><p><strong>The frontend reaches a remote backend over its own <code>ssh</code> child</strong> — no forwarded socket, no local port. Local and remote operation use the same protocol; only the transport differs. See <a href="./../concepts/transport">Transport</a>.</p></li></ul><h2 id="The-machine-role-question" tabindex="-1">The machine-role question <a class="header-anchor" href="#The-machine-role-question" aria-label="Permalink to &quot;The machine-role question {#The-machine-role-question}&quot;">​</a></h2><p>The Q&amp;A asks which of three roles the machine fills:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Role</th><th style="text-align:right;">What runs here</th><th style="text-align:right;">Typical machine</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Frontend client</strong></td><td style="text-align:right;">the frontend only; backend is on a remote</td><td style="text-align:right;">Windows laptop / workstation</td></tr><tr><td style="text-align:right;"><strong>Backend server</strong></td><td style="text-align:right;">the backend + kernel, reached over SSH</td><td style="text-align:right;">Linux server</td></tr><tr><td style="text-align:right;"><strong>All-in-one (local backend)</strong></td><td style="text-align:right;">frontend and backend on one machine</td><td style="text-align:right;">a single Linux box for offline work</td></tr></tbody></table><p>For <strong>Frontend client</strong>, the flow also records this machine as a <code>frontend</code> host and the backend server as a <code>daemon</code> host in <code>hosts.toml</code> (the hub&#39;s copy). The launcher derives everything else — how to dial each host, and the remote&#39;s socket path (<code>sotd session-socket-path sot</code>, always queried, never configured) — from <code>sotd topology plan --self &lt;host&gt;</code> at launch time; there is nothing else to fill in by hand.</p><h2 id="What-gets-written" tabindex="-1">What gets written <a class="header-anchor" href="#What-gets-written" aria-label="Permalink to &quot;What gets written {#What-gets-written}&quot;">​</a></h2><p>The files are <code>hosts.toml</code> (the declared topology), <code>settings.toml</code> (frontend settings) and <code>keybindings.toml</code>. Where each is read from is <a href="/ship-of-tools/stable/ref/config#config-file-locations">Where the files are</a>; their grammar and every setting are in <a href="./../ref/config">Configuration Files</a>. A minimal <code>hosts.toml</code> for one server and one laptop:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hub = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myserver&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myserver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">daemon = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">laptop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frontend = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>The in-app Hosts mode (hotkey <code>h</code>) lists every dialable host with its live connected/unreachable status.</p><h2 id="After-setup" tabindex="-1">After setup <a class="header-anchor" href="#After-setup" aria-label="Permalink to &quot;After setup {#After-setup}&quot;">​</a></h2><p>Once the checklist is complete, the machine has a launcher and a valid host configuration. Continue to <a href="./remote">Going remote</a> to start the app, or take <a href="./tour">Your first session</a>.</p>`,20)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
